async function hashKey(value) {
  const bytes = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest)).map((b) => b.toString(16).padStart(2, "0")).join("");
}
async function requireSeller(ctx, code, key) {
  const db = fullDb(ctx);
  const store = (await db.select().from(storeSettings).where(eq(storeSettings.sellerCode, code.toUpperCase())).limit(1))[0];
  if (!store)
    throw new Error("Seller code or access key is incorrect.");
  if (store.adminKeyHashBcrypt) {
    if (!await Bun.password.verify(key, store.adminKeyHashBcrypt))
      throw new Error("Seller code or access key is incorrect.");
    return store;
  }
  if (!store.adminKeyHash || store.adminKeyHash !== await hashKey(key))
    throw new Error("Seller code or access key is incorrect.");
  await db.update(storeSettings).set({ adminKeyHashBcrypt: await Bun.password.hash(key, { algorithm: "bcrypt", cost: 10 }), updatedAt: new Date }).where(eq(storeSettings.id, store.id));
  return store;
}
