function aggregatePaymentStatus(statuses) {
  const uniq = [...new Set(statuses)];
  if (uniq.length === 1)
    return uniq[0];
  const terminal = new Set(["paid", "refunded", "cancelled"]);
  const open = uniq.filter((s) => !terminal.has(s));
  if (open.length) {
    if (open.includes("failed"))
      return "failed";
    if (open.includes("processing"))
      return "processing";
    return "pending";
  }
  if (uniq.includes("refunded"))
    return "partially_refunded";
  if (uniq.includes("cancelled"))
    return "cancelled";
  return "paid";
}
