async function evaluateCoupon(ctx, code, userId, subtotalPaisa, guestPhone) {
  const db = fullDb(ctx);
  const fail = (message) => ({ valid: false, discount_paisa: 0, free_shipping: false, message });
  const normalized2 = code.trim().toUpperCase();
  if (!normalized2)
    return fail("Please enter a coupon code.");
  const coupon = (await db.select().from(coupons).where(eq(coupons.code, normalized2)).limit(1))[0];
  if (!coupon)
    return fail(`The code "${normalized2}" is not a valid coupon.`);
  if (!coupon.isActive)
    return fail("This coupon is no longer active.");
  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now())
    return fail("This coupon has expired.");
  if (coupon.maxUses != null) {
    const uses = await db.select({ id: couponUsages.id }).from(couponUsages).where(eq(couponUsages.couponId, coupon.id));
    if (uses.length >= coupon.maxUses)
      return fail("This coupon has reached its usage limit.");
  }
  if (coupon.perUserLimit > 0) {
    if (userId) {
      const mine = await db.select({ id: couponUsages.id }).from(couponUsages).where(and(eq(couponUsages.couponId, coupon.id), eq(couponUsages.userId, userId)));
      if (mine.length >= coupon.perUserLimit)
        return fail("You have already used this coupon.");
    } else if (guestPhone) {
      const phone = normalizePhone(guestPhone);
      if (phone) {
        const mine = await db.select({ id: couponUsages.id }).from(couponUsages).where(and(eq(couponUsages.couponId, coupon.id), eq(couponUsages.guestPhone, phone)));
        if (mine.length >= coupon.perUserLimit)
          return fail("This coupon has already been used the maximum number of times for this phone number.");
      }
    }
  }
  if (subtotalPaisa < coupon.minOrderPaisa)
    return fail(`This coupon needs a minimum order of ${formatRs(coupon.minOrderPaisa)}.`);
  const freeShipping = coupon.kind === "free_shipping";
  let discount = coupon.kind === "percent" ? Math.round(subtotalPaisa * coupon.value / 100) : coupon.kind === "fixed" ? Math.min(coupon.value, subtotalPaisa) : 0;
  if (coupon.kind === "percent" && coupon.maxDiscountPaisa != null)
    discount = Math.min(discount, coupon.maxDiscountPaisa);
  return { valid: true, discount_paisa: discount, free_shipping: freeShipping, message: freeShipping ? "Free delivery applied." : `${formatRs(discount)} off applied.`, coupon_id: coupon.id, code: normalized2 };
}
