var ORDER_TRANSITIONS = {
  confirmation_needed: ["confirmed", "cancelled"],
  confirmed: ["packed", "cancelled"],
  packed: ["shipped"],
  shipped: ["out_for_delivery", "delivered", "delivery_failed"],
  out_for_delivery: ["delivered", "delivery_failed"],
  delivery_failed: ["out_for_delivery"],
  delivered: ["return_requested"],
  return_requested: ["returned", "delivered"],
  returned: ["refunded"]
};
async function transitionOrderStatus(ctx, order, next, actor = { type: "seller", id: "" }) {
  const db = fullDb(ctx);
  if (order.status === next)
    return;
  if (!ORDER_TRANSITIONS[order.status]?.includes(next))
    throw new Error("That order status change is not allowed.");
  if (next === "cancelled" && order.groupId) {
    const gp = (await db.select().from(payments).where(eq(payments.groupId, order.groupId)).limit(1))[0];
    if (gp && gp.provider !== "cod") {
      const siblings = await db.select({ id: orders.id }).from(orders).where(eq(orders.groupId, order.groupId));
      if (siblings.length > 1) {
        throw new Error("This parcel is part of a multi-seller online order. Please contact support to arrange a partial cancellation and refund \u2014 a single seller cannot cancel part of a shared online payment.");
      }
    }
  }
  const cfg = await moneyConfig(ctx);
  await db.transaction(async (tx) => {
    const current = (await tx.select().from(orders).where(eq(orders.id, order.id)).limit(1).for("update"))[0];
    if (!current)
      throw new Error("Order not found.");
    if (current.status === next)
      return;
    if (!ORDER_TRANSITIONS[current.status]?.includes(next))
      throw new Error("That order status change is not allowed.");
    if (next === "cancelled") {
      await restoreStockTx(tx, current.id, "order_cancelled", actor.type, actor.id);
    }
    const now = new Date;
    await tx.update(orders).set({ status: next, updatedAt: now, ...next === "delivered" ? { deliveredAt: now } : {} }).where(eq(orders.id, current.id));
    const payment = (await tx.select().from(payments).where(eq(payments.orderId, current.id)).limit(1).for("update"))[0];
    if (payment) {
      let paymentNext = payment.status;
      if (next === "delivered" && payment.provider === "cod" && payment.status === "pending")
        paymentNext = "paid";
      else if (next === "cancelled" && (payment.status === "pending" || payment.status === "processing" || payment.status === "failed"))
        paymentNext = "cancelled";
      else if (next === "refunded")
        paymentNext = "refunded";
      if (paymentNext !== payment.status) {
        await tx.update(payments).set({ status: paymentNext, updatedAt: now }).where(eq(payments.id, payment.id));
        await tx.update(orders).set({ paymentStatus: paymentNext === "paid" ? "paid" : paymentNext === "refunded" ? "refunded" : paymentNext === "cancelled" ? "cancelled" : current.paymentStatus, updatedAt: now }).where(eq(orders.id, current.id));
      }
      if (payment && payment.status !== "paid" && paymentNext === "paid") {
        await accrueSaleCommissionTx(tx, current.id, cfg.commission_default_percent);
      }
    }
  });
  if (order.userId) {
    await notifyUser(ctx, order.userId, { type: "order_status", title: `Order ${order.orderCode}: ${orderStatusLabel(next)}`, body: `Your order ${order.orderCode} is now ${orderStatusLabel(next)}.`, link: "#/orders" });
  }
  if (next === "out_for_delivery" || next === "delivered" || next === "delivery_failed") {
    const event = next;
    await emailBuyerMsg(ctx, order.userId, (to, name2) => shipmentEmail(to, name2, order.orderCode, event, order.carrier, order.trackingNumber));
  }
  ctx.invalidateQueries();
}
