async function recordRefundRequest(ctx, storeId, orderId) {
  const db = fullDb(ctx);
  const order = (await db.select().from(orders).where(and(eq(orders.id, orderId), eq(orders.storeId, storeId))).limit(1))[0];
  if (!order)
    throw new Error("Order not found.");
  if (order.status !== "returned")
    throw new Error("Only returned orders can be refunded.");
  const existing = (await db.select({ id: refunds.id, status: refunds.status }).from(refunds).where(eq(refunds.orderId, order.id)).limit(1))[0];
  if (existing)
    throw new Error(existing.status === "pending" ? "A refund is already waiting with the marketplace team." : "This order's refund has already been recorded.");
  const orderPayment = (await db.select().from(payments).where(eq(payments.orderId, order.id)).limit(1))[0];
  const groupPayment = order.groupId ? (await db.select().from(payments).where(eq(payments.groupId, order.groupId)).limit(1))[0] : undefined;
  const provider = groupPayment && groupPayment.provider !== "cod" ? groupPayment.provider : orderPayment?.provider ?? "cod";
  const paid = provider === "cod" ? orderPayment?.status === "paid" : groupPayment?.status === "paid";
  const requestedBy = `seller:${storeId}`;
  const now = new Date;
  let refundStatus;
  if (!paid) {
    await db.insert(refunds).values({
      orderId: order.id,
      groupId: order.groupId ?? null,
      amountPaisa: 0,
      provider,
      status: "not_required",
      method: "none",
      note: "Cash on delivery \u2014 payment was never collected, so no refund is owed.",
      requestedBy,
      createdAt: now,
      updatedAt: now
    });
    refundStatus = "not_required";
  } else {
    await db.insert(refunds).values({
      orderId: order.id,
      groupId: order.groupId ?? null,
      amountPaisa: order.totalPaisa,
      provider,
      status: "pending",
      method: "manual",
      note: "Refund requested. The marketplace team completes the payment manually through the provider dashboard \u2014 no automatic refund has been sent yet.",
      requestedBy,
      createdAt: now,
      updatedAt: now
    });
    refundStatus = "pending";
  }
  if (order.userId) {
    await notifyUser(ctx, order.userId, {
      type: "payment",
      title: refundStatus === "pending" ? `Refund requested for ${order.orderCode}` : `Return closed for ${order.orderCode}`,
      body: refundStatus === "pending" ? `A refund of ${formatRs(order.totalPaisa)} for order ${order.orderCode} is with our team. It is completed manually, so it can take a few working days.` : `Your return for order ${order.orderCode} is closed. It was Cash on Delivery and no payment was collected, so there is nothing to refund.`,
      link: "#/orders"
    });
  }
  await emailBuyer(ctx, order.userId, refundStatus === "pending" ? `Refund requested for order ${order.orderCode}` : `Return closed for order ${order.orderCode}`, refundStatus === "pending" ? `A refund of ${formatRs(order.totalPaisa)} for order ${order.orderCode} is waiting with our team. We complete refunds manually through the payment provider, so please allow a few working days \u2014 we will confirm here once the money is on its way back.` : `Your return for order ${order.orderCode} is closed. It was Cash on Delivery and no payment was collected, so no refund is owed.`);
  await audit(ctx, "seller", String(storeId), "refund_requested", "order", String(order.id), `${order.orderCode} \u2192 ${refundStatus}`);
  ctx.invalidateQueries();
  return { ok: true, refund_status: refundStatus };
}
var MONEY_DEFAULTS = { commission_default_percent: 5, payout_available_after_days: 7, payout_min_paisa: 50000 };
async function moneyConfig(ctx) {
  const db = fullDb(ctx);
  const rows = await db.select().from(platformSettings);
  const get2 = (k) => rows.find((r) => r.key === k)?.value;
  const int2 = (v, dflt, min, max) => {
    const n = Number(v);
    return v != null && Number.isInteger(n) && n >= min && n <= max ? n : dflt;
  };
  return {
    commission_default_percent: int2(get2("commission_default_percent"), MONEY_DEFAULTS.commission_default_percent, 0, 90),
    payout_available_after_days: int2(get2("payout_available_after_days"), MONEY_DEFAULTS.payout_available_after_days, 0, 90),
    payout_min_paisa: int2(get2("payout_min_paisa"), MONEY_DEFAULTS.payout_min_paisa, 0, 1e8)
  };
}
function resolveRuleForLine(rules, storeId, productId, category, defaultPercent) {
  const now = Date.now();
  const named = (r, kind) => `${r.percent}% ${kind}${r.label ? ` \u201C${r.label}\u201D` : ""} (rule #${r.id})`;
  const product = rules.find((r) => r.scope === "product" && r.scopeId === String(productId));
  if (product)
    return { percent: product.percent, ruleId: product.id, source: named(product, "product rule") };
  const seller = rules.find((r) => r.scope === "seller" && r.scopeId === String(storeId));
  if (seller)
    return { percent: seller.percent, ruleId: seller.id, source: named(seller, "seller rule") };
  const cat = rules.find((r) => r.scope === "category" && r.scopeId === category);
  if (cat)
    return { percent: cat.percent, ruleId: cat.id, source: named(cat, "category rule") };
  const camp = rules.find((r) => r.scope === "campaign" && (!r.startsAt || r.startsAt.getTime() <= now) && (!r.endsAt || r.endsAt.getTime() >= now));
  if (camp)
    return { percent: camp.percent, ruleId: camp.id, source: named(camp, "campaign") };
  const plat = rules.find((r) => r.scope === "platform");
  if (plat)
    return { percent: plat.percent, ruleId: plat.id, source: named(plat, "platform rule") };
  return { percent: defaultPercent, ruleId: null, source: `${defaultPercent}% platform default` };
}
async function ledgerBalanceTx(tx, storeId) {
  const last = (await tx.select({ b: sellerLedger.balanceAfterPaisa }).from(sellerLedger).where(eq(sellerLedger.storeId, storeId)).orderBy(desc(sellerLedger.id)).limit(1).for("update"))[0];
  return last?.b ?? 0;
}
async function insertLedgerTx(tx, storeId, row) {
  const after = await ledgerBalanceTx(tx, storeId) + row.amountPaisa;
  await tx.insert(sellerLedger).values({
    storeId,
    orderId: row.orderId ?? null,
    type: row.type,
    amountPaisa: row.amountPaisa,
    balanceAfterPaisa: after,
    ruleId: row.ruleId ?? null,
    payoutId: row.payoutId ?? null,
    ledgerKey: row.ledgerKey ?? null,
    note: row.note,
    createdAt: new Date
  }).onConflictDoNothing({ target: sellerLedger.ledgerKey });
}
async function accrueSaleCommissionTx(tx, orderId, defaultPercent) {
  const done = (await tx.select({ id: sellerLedger.id }).from(sellerLedger).where(eq(sellerLedger.ledgerKey, `sale:${orderId}`)).limit(1))[0];
  if (done)
    return;
  const order = (await tx.select().from(orders).where(eq(orders.id, orderId)).limit(1).for("update"))[0];
  if (!order || order.paymentStatus !== "paid")
    return;
  const items = await tx.select().from(orderItems).where(eq(orderItems.orderId, orderId));
  const productIds = [...new Set(items.map((i) => i.productId))];
  const products2 = productIds.length ? await tx.select().from(products).where(inArray(products.id, productIds)) : [];
  const byId = new Map(products2.map((p) => [p.id, p]));
  const rules = await tx.select().from(commissionRules).where(eq(commissionRules.isActive, true));
  let commission = 0;
  const parts = [];
  const ruleIds = new Set;
  for (const item of items) {
    const product = byId.get(item.productId);
    const line2 = item.unitPricePaisa * item.quantity;
    const r = resolveRuleForLine(rules, order.storeId, item.productId, product?.category ?? "", defaultPercent);
    const cut = Math.round(line2 * r.percent / 100);
    commission += cut;
    if (r.ruleId != null)
      ruleIds.add(r.ruleId);
    parts.push(`${formatRs(line2)} @ ${r.source} \u2192 ${formatRs(cut)}`);
  }
  await insertLedgerTx(tx, order.storeId, {
    orderId,
    type: "sale",
    amountPaisa: order.subtotalPaisa,
    ledgerKey: `sale:${orderId}`,
    note: `Sale ${order.orderCode}: ${items.length} line(s), ${formatRs(order.subtotalPaisa)} gross of goods (delivery fee excluded).`
  });
  await insertLedgerTx(tx, order.storeId, {
    orderId,
    type: "commission",
    amountPaisa: -commission,
    ruleId: ruleIds.size === 1 ? [...ruleIds][0] : null,
    ledgerKey: `commission:${orderId}`,
    note: `Commission on ${order.orderCode}: ${parts.join("; ") || "no order lines"}.`
  });
}
async function reverseCommissionTx(tx, orderId, orderCode) {
  const sale = (await tx.select().from(sellerLedger).where(eq(sellerLedger.ledgerKey, `sale:${orderId}`)).limit(1).for("update"))[0];
  const comm = (await tx.select().from(sellerLedger).where(eq(sellerLedger.ledgerKey, `commission:${orderId}`)).limit(1).for("update"))[0];
  if (!sale && !comm)
    return;
  const storeId = (sale ?? comm).storeId;
  if (sale) {
    await insertLedgerTx(tx, storeId, {
      orderId,
      type: "refund",
      amountPaisa: -sale.amountPaisa,
      ledgerKey: `refund:${orderId}`,
      note: `Refund ${orderCode}: sale of ${formatRs(sale.amountPaisa)} reversed.`
    });
  }
  if (comm) {
    await insertLedgerTx(tx, storeId, {
      orderId,
      type: "commission",
      amountPaisa: -comm.amountPaisa,
      ruleId: comm.ruleId,
      ledgerKey: `commission-reversal:${orderId}`,
      note: `Commission reversed \u2014 ${orderCode} refunded (${formatRs(-comm.amountPaisa)} returned to seller).`
    });
  }
}
async function sellerBalances(ctx, storeId) {
  const cfg = await moneyConfig(ctx);
  const db = fullDb(ctx);
  const [rows, orders2, payouts] = await Promise.all([
    db.select().from(sellerLedger).where(eq(sellerLedger.storeId, storeId)).orderBy(desc(sellerLedger.id)).limit(1e4),
    db.select({ id: orders.id, status: orders.status, deliveredAt: orders.deliveredAt }).from(orders).where(eq(orders.storeId, storeId)),
    db.select().from(sellerPayouts).where(eq(sellerPayouts.storeId, storeId)).orderBy(desc(sellerPayouts.id)).limit(1000)
  ]);
  const holdMs = cfg.payout_available_after_days * 86400000;
  const now = Date.now();
  const orderById = new Map(orders2.map((o) => [o.id, o]));
  let pending = 0, available = 0, paid = 0;
  for (const r of rows) {
    if (r.type === "payout") {
      available += r.amountPaisa;
      paid += -r.amountPaisa;
      continue;
    }
    const mature = r.orderId == null ? true : (() => {
      const o = orderById.get(r.orderId);
      return !!o && o.status === "delivered" && !!o.deliveredAt && o.deliveredAt.getTime() + holdMs <= now;
    })();
    if (mature)
      available += r.amountPaisa;
    else
      pending += r.amountPaisa;
  }
  const reserved = payouts.filter((p) => p.status === "requested" || p.status === "processing").reduce((n, p) => n + p.amountPaisa, 0);
  return {
    pending_paisa: pending,
    available_paisa: available,
    reserved_paisa: reserved,
    requestable_paisa: Math.max(0, available - reserved),
    paid_paisa: paid,
    hold_days: cfg.payout_available_after_days,
    min_payout_paisa: cfg.payout_min_paisa,
    default_commission_percent: cfg.commission_default_percent
  };
}
function maskAccountNumber(raw) {
  const digits = (raw ?? "").replace(/\D/g, "");
  if (digits.length < 4)
    return "\u2022\u2022\u2022\u2022";
  return `\u2022\u2022\u2022\u2022${digits.slice(-4)}`;
}
async function ensureGroupInvoice(ctx, groupId) {
  const db = fullDb(ctx);
  let lastErr = null;
  for (let attempt = 0;attempt < 3; attempt++) {
    try {
      return db.transaction(async (tx) => {
        const existing = (await tx.select().from(invoices).where(eq(invoices.groupId, groupId)).limit(1))[0];
        if (existing)
          return { id: existing.id, invoiceNo: existing.invoiceNo, issuedAt: existing.issuedAt };
        const key = `INV-${new Date().getFullYear()}`;
        let row = (await tx.select().from(invoiceCounters).where(eq(invoiceCounters.key, key)).limit(1).for("update"))[0];
        if (!row) {
          await tx.insert(invoiceCounters).values({ key, last: 0 });
          row = { key, last: 0 };
        }
        const next = row.last + 1;
        await tx.update(invoiceCounters).set({ last: next }).where(eq(invoiceCounters.key, key));
        const invoiceNo = `${key}-${String(next).padStart(6, "0")}`;
        const now = new Date;
        const inserted = await tx.insert(invoices).values({ invoiceNo, orderId: null, groupId, issuedAt: now, createdAt: now }).returning({ id: invoices.id });
        const inv = inserted[0];
        if (!inv)
          throw new Error("The invoice could not be created.");
        return { id: inv.id, invoiceNo, issuedAt: now };
      });
    } catch (e) {
      lastErr = e;
      if (!(e instanceof Error) || !/UNIQUE constraint failed/i.test(e.message))
        throw e;
    }
  }
  throw lastErr instanceof Error ? lastErr : new Error("The invoice could not be created.");
}
function parseCsv(text2) {
  const rows = [];
  let row = [], field = "", inQuotes = false;
  for (let i = 0;i < text2.length; i++) {
    const c = text2[i];
    if (inQuotes) {
      if (c === '"') {
        if (text2[i + 1] === '"') {
          field += '"';
          i++;
        } else
          inQuotes = false;
      } else
        field += c;
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      row.push(field);
      field = "";
    } else if (c === `
`) {
      row.push(field);
      rows.push(row);
      row = [];
      field = "";
    } else if (c === "\r") {} else {
      field += c;
    }
  }
  if (field !== "" || row.length > 0) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}
