  saveStoreAssets: defineAction({
    request: exports_external.object({ ...sellerAuthFields, logo_url: storeAssetUrlField.nullish(), banner_url: storeAssetUrlField.nullish() }),
    response: exports_external.object({ ok: exports_external.literal(true), logo_url: exports_external.string().nullable(), banner_url: exports_external.string().nullable() }),
    async handler(ctx, args) {
      const store = await resolveSeller(ctx, args);
      assertSellerCanSell(store);
      const db = fullDb(ctx);
      const pick2 = async (incoming, current, kind) => {
        if (incoming === undefined)
          return current;
        const url2 = incoming?.trim() || null;
        if (url2 && !isExpectedUploadUrl(url2, "store"))
          throw new Error(`The ${kind} image must be uploaded through the studio uploader.`);
        if (current && current !== url2)
          await deleteStoredUpload(current);
        return url2;
      };
      const logoUrl = await pick2(args.logo_url, store.logoUrl ?? null, "logo");
      const bannerUrl = await pick2(args.banner_url, store.bannerUrl ?? null, "banner");
      await db.update(storeSettings).set({ logoUrl, bannerUrl, updatedAt: new Date }).where(eq(storeSettings.id, store.id));
      await audit(ctx, "seller", String(store.id), "store_assets_updated", "store", String(store.id), `logo=${logoUrl ? "set" : "none"} banner=${bannerUrl ? "set" : "none"}`);
      ctx.invalidateQueries();
      return { ok: true, logo_url: logoUrl, banner_url: bannerUrl };
    }
  }),
  createProduct: defineAction({
    request: exports_external.object({ ...sellerAuthFields, name: exports_external.string().trim().min(2).max(80), category: exports_external.string().trim().min(2).max(40), description: exports_external.string().trim().min(8).max(500), price_paisa: exports_external.number().int().positive(), delivery_fee_paisa: exports_external.number().int().min(0), stock: exports_external.number().int().min(0).max(1e5), brand: exports_external.string().trim().max(40).optional(), original_price_paisa: exports_external.number().int().positive().optional(), image_url: imageUrlField.optional(), low_stock_threshold: exports_external.number().int().min(0).max(1000).optional(), sku: exports_external.string().trim().max(40).optional(), is_active: exports_external.boolean().optional().default(false) }),
    response: exports_external.object({ id: exports_external.number(), is_active: exports_external.boolean() }),
    async handler(ctx, args) {
      const store = await resolveSeller(ctx, args);
      assertSellerCanSell(store);
      if (args.original_price_paisa != null && args.original_price_paisa <= args.price_paisa)
        throw new Error("The original price must be higher than the selling price.");
      const db = fullDb(ctx);
      const sku = normalizeSku(args.sku);
      if (sku) {
        const clash = (await db.select({ id: products.id }).from(products).where(and(eq(products.storeId, store.id), eq(products.sku, sku))).limit(1))[0];
        if (clash)
          throw new Error(`The SKU "${sku}" is already used by another product in this shop.`);
      }
      const isActive = store.status === "active" && args.is_active;
      const approvalStatus = store.status === "active" ? "approved" : "pending";
      const result = await db.insert(products).values({ storeId: store.id, name: args.name, category: args.category, description: args.description, pricePaisa: args.price_paisa, deliveryFeePaisa: args.delivery_fee_paisa, stock: args.stock, brand: args.brand?.trim() || null, originalPricePaisa: args.original_price_paisa ?? null, imageUrl: args.image_url ?? null, lowStockThreshold: args.low_stock_threshold ?? 5, sku, isActive, approvalStatus, updatedAt: new Date }).returning({ id: products.id });
      const row = result[0];
      if (!row)
        throw new Error("The product could not be saved.");
      if (args.stock > 0) {
        await db.insert(stockMovements).values({ productId: row.id, variantId: 0, change: args.stock, stockAfter: args.stock, reason: "product_created", actorType: "seller", actorId: String(store.id), createdAt: new Date });
      }
      ctx.invalidateQueries();
      return { id: row.id, is_active: isActive };
    }
  }),
  updateProduct: defineAction({
    request: exports_external.object({ ...sellerAuthFields, id: exports_external.number().int().positive(), name: exports_external.string().trim().min(2).max(80), category: exports_external.string().trim().min(2).max(40), description: exports_external.string().trim().min(8).max(500), price_paisa: exports_external.number().int().positive(), delivery_fee_paisa: exports_external.number().int().min(0), stock: exports_external.number().int().min(0).max(1e5), is_active: exports_external.boolean(), image_url: imageUrlField.nullish(), sku: exports_external.string().trim().max(40).nullish(), brand: exports_external.string().trim().max(40).nullish(), original_price_paisa: exports_external.number().int().positive().nullish(), low_stock_threshold: exports_external.number().int().min(0).max(1000).nullish() }),
    response: exports_external.object({ ok: exports_external.literal(true) }),
    async handler(ctx, args) {
      const store = await resolveSeller(ctx, args);
      assertSellerCanSell(store);
      const db = fullDb(ctx);
      const before = (await db.select().from(products).where(and(eq(products.id, args.id), eq(products.storeId, store.id))).limit(1))[0];
      if (!before)
        throw new Error("Product not found.");
      if (args.original_price_paisa != null && args.original_price_paisa <= args.price_paisa)
        throw new Error("The original price must be higher than the selling price.");
      const sku = args.sku === undefined ? before.sku : normalizeSku(args.sku);
      if (sku) {
        const clash = (await db.select({ id: products.id }).from(products).where(and(eq(products.storeId, store.id), eq(products.sku, sku))).limit(1))[0];
        if (clash && clash.id !== args.id)
          throw new Error(`The SKU "${sku}" is already used by another product in this shop.`);
      }
      const isActive = store.status === "active" && args.is_active;
      await db.update(products).set({ name: args.name, category: args.category, description: args.description, pricePaisa: args.price_paisa, deliveryFeePaisa: args.delivery_fee_paisa, stock: args.stock, isActive, imageUrl: args.image_url ?? before.imageUrl, sku, brand: args.brand === undefined ? before.brand : args.brand?.trim() || null, originalPricePaisa: args.original_price_paisa === undefined ? before.originalPricePaisa : args.original_price_paisa, lowStockThreshold: args.low_stock_threshold ?? before.lowStockThreshold, updatedAt: new Date }).where(and(eq(products.id, args.id), eq(products.storeId, store.id)));
      if (args.stock !== before.stock) {
        await db.insert(stockMovements).values({ productId: args.id, variantId: 0, change: args.stock - before.stock, stockAfter: args.stock, reason: "manual_adjust", actorType: "seller", actorId: String(store.id), createdAt: new Date });
      }
      const priceLowered = args.price_paisa < before.pricePaisa;
      const backInStock = before.stock <= 0 && args.stock > 0;
      if (priceLowered || backInStock) {
        const items = await db.select().from(wishlistItems).where(eq(wishlistItems.productId, args.id));
        if (items.length) {
          const wls = await db.select().from(wishlists).where(inArray(wishlists.id, [...new Set(items.map((i) => i.wishlistId))]));
          const userIds = [...new Set(wls.map((w) => w.userId))];
          for (const uid of userIds) {
            if (priceLowered)
              await notifyUser(ctx, uid, { type: "price_drop", title: `Price drop: ${args.name}`, body: `${args.name} is now ${formatRs(args.price_paisa)} (was ${formatRs(before.pricePaisa)}).`, link: `#/product/${args.id}` });
            if (backInStock)
              await notifyUser(ctx, uid, { type: "back_in_stock", title: `Back in stock: ${args.name}`, body: `${args.name} is available again \u2014 order before it sells out.`, link: `#/product/${args.id}` });
          }
        }
      }
      ctx.invalidateQueries();
      return { ok: true };
    }
  }),
