      seller: exports_external.object({ id: exports_external.number(), seller_code: exports_external.string(), store_name: exports_external.string(), location: exports_external.string(), phone: exports_external.string(), email: exports_external.string().nullable(), status: sellerStatus, email_verified: exports_external.boolean(), description: exports_external.string(), created_at: exports_external.string() }),
