  adminSaveCommissionRule: defineAction({
    request: exports_external.object({
      authToken: authTokenField,
      scope: exports_external.enum(["platform", "category", "seller", "product", "campaign"]),
      scope_id: exports_external.string().trim().max(80).default(""),
      percent: exports_external.number().int().min(0).max(90),
      label: exports_external.string().trim().max(80).optional(),
      starts_at: exports_external.string().trim().max(40).optional(),
      ends_at: exports_external.string().trim().max(40).optional(),
      is_active: exports_external.boolean().default(true)
    }),
    response: exports_external.object({ ok: exports_external.literal(true), rule_id: exports_external.number() }),
    async handler(ctx, args) {
      const auth = await requireAuth(ctx, args.authToken, "admin");
      const db = fullDb(ctx);
      let scopeId = args.scope_id.trim();
      if (args.scope === "platform") {
        scopeId = "";
      } else if (args.scope === "category") {
        if (!scopeId)
          throw new Error("Choose a category for a category rule.");
        const cats = await db.select({ category: products.category }).from(products);
        if (!cats.some((c) => c.category === scopeId))
          throw new Error(`No product uses the category \u201C${scopeId}\u201D yet \u2014 create a product in it first.`);
      } else if (args.scope === "seller") {
        if (!/^\d+$/.test(scopeId))
          throw new Error("A seller rule needs a numeric seller id.");
        const store = (await db.select({ id: storeSettings.id }).from(storeSettings).where(eq(storeSettings.id, Number(scopeId))).limit(1))[0];
        if (!store)
          throw new Error("That seller does not exist.");
      } else if (args.scope === "product") {
        if (!/^\d+$/.test(scopeId))
          throw new Error("A product rule needs a numeric product id.");
        const product = (await db.select({ id: products.id }).from(products).where(eq(products.id, Number(scopeId))).limit(1))[0];
        if (!product)
          throw new Error("That product does not exist.");
      } else {
        if (!/^[a-z0-9][a-z0-9-]{1,39}$/i.test(scopeId))
          throw new Error("A campaign code uses letters, numbers and dashes (2\u201340 characters).");
      }
      const parseDate = (v, name2) => {
        if (!v)
          return null;
        const d = new Date(v);
        if (Number.isNaN(d.getTime()))
          throw new Error(`${name2} is not a valid date.`);
        return d;
      };
      const startsAt = parseDate(args.starts_at, "The campaign start");
      const endsAt = parseDate(args.ends_at, "The campaign end");
      if (startsAt && endsAt && startsAt >= endsAt)
        throw new Error("The campaign must end after it starts.");
      const now = new Date;
      const existing = (await db.select().from(commissionRules).where(and(eq(commissionRules.scope, args.scope), eq(commissionRules.scopeId, scopeId))).limit(1))[0];
      let ruleId;
      if (existing) {
        await db.update(commissionRules).set({ percent: args.percent, label: args.label?.trim() ?? existing.label, startsAt, endsAt, isActive: args.is_active }).where(eq(commissionRules.id, existing.id));
        ruleId = existing.id;
      } else {
        const inserted = await db.insert(commissionRules).values({ scope: args.scope, scopeId, percent: args.percent, label: args.label?.trim() ?? "", startsAt, endsAt, isActive: args.is_active, createdAt: now }).returning({ id: commissionRules.id });
        if (!inserted[0])
          throw new Error("Could not save the rule.");
        ruleId = inserted[0].id;
      }
      await audit(ctx, "admin", auth.id, "commission_rule_saved", "commission_rule", String(ruleId), `${args.scope}:${scopeId || "platform"} \u2192 ${args.percent}%${args.is_active ? "" : " (inactive)"}`);
      if (args.is_active) {
        const scopeLabel = args.scope === "platform" ? "" : args.scope === "category" ? ` on products in the \u201C${scopeId}\u201D category` : args.scope === "seller" ? ` on your shop\u2019s sales` : args.scope === "product" ? ` on one of your products` : ` for the \u201C${scopeId}\u201D campaign`;
        let storeIds;
        if (args.scope === "seller") {
          storeIds = [Number(scopeId)];
        } else if (args.scope === "product") {
          const p = (await db.select({ storeId: products.storeId }).from(products).where(eq(products.id, Number(scopeId))).limit(1))[0];
          storeIds = p ? [p.storeId] : [];
        } else if (args.scope === "category") {
          const prods = await db.select({ storeId: products.storeId }).from(products).where(eq(products.category, scopeId));
          storeIds = [...new Set(prods.map((p) => p.storeId))];
        } else {
          const actives = await db.select({ id: storeSettings.id }).from(storeSettings).where(eq(storeSettings.status, "active"));
          storeIds = actives.map((s) => s.id);
        }
        for (const sid of storeIds) {
          await emailSellerMsg(ctx, sid, (to, storeName) => commissionChangeEmail(to, storeName, scopeLabel, args.percent));
        }
      }
      ctx.invalidateQueries();
      return { ok: true, rule_id: ruleId };
    }
  }),
  adminDeleteCommissionRule: defineAction({
    request: exports_external.object({ authToken: authTokenField, rule_id: exports_external.number().int().positive() }),
    response: exports_external.object({ ok: exports_external.literal(true) }),
    async handler(ctx, args) {
      const auth = await requireAuth(ctx, args.authToken, "admin");
      const db = fullDb(ctx);
      const rule = (await db.select().from(commissionRules).where(eq(commissionRules.id, args.rule_id)).limit(1))[0];
      if (!rule)
        throw new Error("Rule not found.");
      if (rule.isActive)
        throw new Error("Deactivate this rule before deleting it \u2014 active rules price live sales.");
      const used = (await db.select({ id: sellerLedger.id }).from(sellerLedger).where(eq(sellerLedger.ruleId, rule.id)).limit(1))[0];
      if (used)
        throw new Error("This rule has already priced real orders \u2014 deactivate it instead of deleting, so the ledger history stays auditable.");
      await db.delete(commissionRules).where(eq(commissionRules.id, rule.id));
      await audit(ctx, "admin", auth.id, "commission_rule_deleted", "commission_rule", String(rule.id), `${rule.scope}:${rule.scopeId || "platform"} (${rule.percent}%)`);
      ctx.invalidateQueries();
      return { ok: true };
    }
  }),
