      payouts: exports_external.array(exports_external.object({ id: exports_external.number(), amount_paisa: exports_external.number(), status: exports_external.enum(["requested", "processing", "completed", "failed", "cancelled"]), method: exports_external.enum(["bank", "esewa", "khalti"]), destination: exports_external.string(), reference: exports_external.string().nullable(), note: exports_external.string(), created_at: exports_external.string(), updated_at: exports_external.string() }))
