  sellerSavePayoutDetails: defineAction({
    request: exports_external.object({
      ...sellerAuthFields,
      bank_name: exports_external.string().trim().max(80).optional(),
      account_name: exports_external.string().trim().max(80).optional(),
      account_number: exports_external.string().trim().max(30).optional(),
      esewa_id: exports_external.string().trim().max(40).optional(),
      khalti_id: exports_external.string().trim().max(40).optional(),
      remove: exports_external.array(exports_external.enum(["bank", "esewa", "khalti"])).max(3).optional()
    }),
    response: exports_external.object({ ok: exports_external.literal(true) }),
    async handler(ctx, args) {
      const store = await resolveSeller(ctx, args);
      const db = fullDb(ctx);
      const existing = (await db.select().from(sellerPayoutDetails).where(eq(sellerPayoutDetails.storeId, store.id)).limit(1))[0];
      const keep = (provided, current) => {
        if (provided === undefined)
          return current;
        const t = provided.trim();
        return t ? t : current;
      };
      const removals = new Set(args.remove ?? []);
      let bankName = existing?.bankName ?? null;
      let accountName = existing?.accountName ?? null;
      let accountNumber = existing?.accountNumber ?? null;
      if (removals.has("bank")) {
        bankName = accountName = accountNumber = null;
      } else {
        bankName = keep(args.bank_name, bankName);
        accountName = keep(args.account_name, accountName);
        accountNumber = keep(args.account_number, accountNumber);
      }
      const bankFields = [bankName, accountName, accountNumber];
      if (bankFields.some((f) => f !== null) && bankFields.some((f) => f === null)) {
        throw new Error("Bank payouts need all three: bank name, account holder name and account number.");
      }
      if (accountNumber && !/^[0-9][0-9 \-]{5,23}$/.test(accountNumber)) {
        throw new Error("That account number does not look right \u2014 6 to 24 digits.");
      }
      let esewaId = existing?.esewaId ?? null;
      let khaltiId = existing?.khaltiId ?? null;
      esewaId = removals.has("esewa") ? null : keep(args.esewa_id, esewaId);
      khaltiId = removals.has("khalti") ? null : keep(args.khalti_id, khaltiId);
      if (!bankName && !esewaId && !khaltiId) {
        throw new Error("Add at least one payout method: bank details, an eSewa ID or a Khalti ID.");
      }
      const now = new Date;
      await db.insert(sellerPayoutDetails).values({ storeId: store.id, bankName, accountName, accountNumber, esewaId, khaltiId, updatedAt: now }).onConflictDoUpdate({ target: sellerPayoutDetails.storeId, set: { bankName, accountName, accountNumber, esewaId, khaltiId, updatedAt: now } });
      const changed = ["bank", "esewa", "khalti"].filter((m) => args[`${m === "bank" ? "bank_name" : `${m}_id`}`] !== undefined || removals.has(m));
      await audit(ctx, "seller", String(store.id), "payout_details_saved", "seller_payout_details", String(store.id), `methods updated: ${changed.join(", ") || "none"}`);
      ctx.invalidateQueries();
      return { ok: true };
    }
  }),
  sellerRequestPayout: defineAction({
    request: exports_external.object({ ...sellerAuthFields, amount_paisa: exports_external.number().int().positive().max(1e8), method: exports_external.enum(["bank", "esewa", "khalti"]) }),
    response: exports_external.object({ ok: exports_external.literal(true), payout_id: exports_external.number() }),
    async handler(ctx, args) {
      const store = await resolveSeller(ctx, args);
      const db = fullDb(ctx);
      const details = (await db.select().from(sellerPayoutDetails).where(eq(sellerPayoutDetails.storeId, store.id)).limit(1))[0];
      let destination;
      if (args.method === "bank") {
        if (!details?.bankName || !details?.accountName || !details?.accountNumber)
          throw new Error("Add your bank details first \u2014 bank name, account holder and account number.");
        destination = `${details.bankName} \u2022 ${maskAccountNumber(details.accountNumber)}`;
      } else if (args.method === "esewa") {
        if (!details?.esewaId)
          throw new Error("Add your eSewa ID first, under payout details.");
        destination = `eSewa ${details.esewaId}`;
      } else {
        if (!details?.khaltiId)
          throw new Error("Add your Khalti ID first, under payout details.");
        destination = `Khalti ${details.khaltiId}`;
      }
      const b = await sellerBalances(ctx, store.id);
      if (b.requestable_paisa < b.min_payout_paisa) {
        throw new Error(`Payouts need at least ${formatRs(b.min_payout_paisa)} available. You have ${formatRs(b.requestable_paisa)} ready right now.`);
      }
      if (args.amount_paisa > b.requestable_paisa) {
        throw new Error(`You only have ${formatRs(b.requestable_paisa)} available to withdraw.`);
      }
      if (args.amount_paisa < b.min_payout_paisa) {
        throw new Error(`The minimum payout is ${formatRs(b.min_payout_paisa)}.`);
      }
      const now = new Date;
      const inserted = await db.insert(sellerPayouts).values({
        storeId: store.id,
        amountPaisa: args.amount_paisa,
        status: "requested",
        method: args.method,
        destination,
        createdAt: now,
        updatedAt: now
      }).returning({ id: sellerPayouts.id });
      if (!inserted[0])
        throw new Error("Could not create the payout request.");
      const payoutId = inserted[0].id;
      await audit(ctx, "seller", String(store.id), "payout_requested", "seller_payout", String(payoutId), `${formatRs(args.amount_paisa)} via ${args.method} \u2192 ${destination}`);
      await emailSeller(ctx, store.id, `Payout requested: ${formatRs(args.amount_paisa)}`, `We received your payout request for ${formatRs(args.amount_paisa)} via ${args.method} (${destination}). Our team will process it shortly \u2014 you can follow its progress under Earnings in the studio.`);
      await notifyAdmin(`Payout request needs action: ${formatRs(args.amount_paisa)}`, `${store.storeName} (${store.sellerCode}) requested a payout of ${formatRs(args.amount_paisa)} via ${args.method} \u2192 ${destination}.

Review it in the admin panel under Payouts.`);
      ctx.invalidateQueries();
      return { ok: true, payout_id: payoutId };
    }
  }),
  sellerCancelPayout: defineAction({
    request: exports_external.object({ ...sellerAuthFields, payout_id: exports_external.number().int().positive() }),
    response: exports_external.object({ ok: exports_external.literal(true) }),
    async handler(ctx, args) {
      const store = await resolveSeller(ctx, args);
      await fullDb(ctx).transaction(async (tx) => {
        const p = (await tx.select().from(sellerPayouts).where(eq(sellerPayouts.id, args.payout_id)).limit(1).for("update"))[0];
        if (!p || p.storeId !== store.id)
          throw new Error("Payout not found.");
        if (p.status !== "requested")
          throw new Error("Only a payout that is still waiting can be cancelled.");
        await tx.update(sellerPayouts).set({ status: "cancelled", updatedAt: new Date }).where(eq(sellerPayouts.id, p.id));
      });
      await audit(ctx, "seller", String(store.id), "payout_cancelled", "seller_payout", String(args.payout_id), "cancelled by seller");
      ctx.invalidateQueries();
      return { ok: true };
    }
  }),
