  getProductDetail: defineAction({
    request: exports_external.object({ product_id: exports_external.number().int().positive(), authToken: authTokenField }),
    response: exports_external.object({
      product: productShape,
      variants: exports_external.array(variantShape),
      specs: exports_external.array(specShape),
      reviews: exports_external.array(exports_external.object({ id: exports_external.number(), reviewer_name: exports_external.string(), rating: exports_external.number(), body: exports_external.string(), created_at: exports_external.string() })),
      related: exports_external.array(productShape),
      frequently_bought_together: exports_external.array(productShape),
      seller: exports_external.object({ store_name: exports_external.string(), location: exports_external.string(), rating: exports_external.number().nullable(), product_count: exports_external.number(), verified: exports_external.boolean() })
    }),
    async handler(ctx, args) {
      const db = fullDb(ctx);
      const actives = await activeStoreIds(ctx);
      const pubs = publicOnly(await productRows(ctx), actives);
      const product = pubs.find((p) => p.id === args.product_id);
      if (!product)
        throw new Error("That product was not found.");
      const reviewRows = await db.select().from(reviews).where(eq(reviews.productId, args.product_id)).orderBy(desc(reviews.createdAt));
      const related = pubs.filter((p) => p.category === product.category && p.id !== product.id).slice(0, 4);
      const ownItems = await db.select().from(orderItems).where(eq(orderItems.productId, args.product_id));
      const orderIds = [...new Set(ownItems.map((i) => i.orderId))];
      let frequentlyBoughtTogether = [];
      if (orderIds.length) {
        const others = await db.select().from(orderItems).where(inArray(orderItems.orderId, orderIds));
        const counts = new Map;
        for (const o of others)
          if (o.productId !== args.product_id)
            counts.set(o.productId, (counts.get(o.productId) ?? 0) + 1);
        const byId = new Map(pubs.map((p) => [p.id, p]));
        frequentlyBoughtTogether = [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 4).flatMap(([id]) => {
          const p = byId.get(id);
          return p ? [p] : [];
        });
      }
      const store = (await db.select().from(storeSettings).where(eq(storeSettings.id, product.store_id)).limit(1))[0];
      const sellerProducts = pubs.filter((p) => p.store_id === product.store_id);
      const sellerReviews = sellerProducts.length ? await db.select().from(reviews).where(inArray(reviews.productId, sellerProducts.map((p) => p.id))) : [];
      const userId = await buyerIdOf(ctx, args.authToken);
      await recordProductView(ctx, args.product_id, userId);
      if (userId) {
        await db.insert(recentlyViewed).values({ userId, productId: args.product_id, viewedAt: new Date }).onConflictDoUpdate({ target: [recentlyViewed.userId, recentlyViewed.productId], set: { viewedAt: new Date } });
      }
      return {
        product,
        variants: (await activeVariants(ctx, product.id)).map((v) => ({ id: v.id, label: v.label, sku: v.sku ?? null, price_paisa: v.pricePaisa ?? null, stock: v.stock, is_active: v.isActive })),
        specs: (await activeSpecs(ctx, product.id)).map((s) => ({ id: s.id, label: s.label, value: s.value })),
        reviews: reviewRows.map((r) => ({ id: r.id, reviewer_name: r.reviewerName, rating: r.rating, body: r.body, created_at: r.createdAt.toISOString() })),
        related,
        frequently_bought_together: frequentlyBoughtTogether,
        seller: {
          store_name: store?.storeName ?? product.store_name,
          location: store?.location ?? "",
          rating: sellerReviews.length ? sellerReviews.reduce((n, r) => n + r.rating, 0) / sellerReviews.length : null,
          product_count: sellerProducts.length,
          verified: (store?.status ?? "") === "active" && !!store?.email
        }
      };
    }
  }),
