  searchProducts: defineAction({
    request: exports_external.object({
      query: exports_external.string().trim().max(120).default(""),
      category: exports_external.string().trim().max(40).optional(),
      brand: exports_external.string().trim().max(40).optional(),
      min_price_paisa: exports_external.number().int().min(0).optional(),
      max_price_paisa: exports_external.number().int().min(0).optional(),
      min_rating: exports_external.number().min(0).max(5).optional(),
      in_stock_only: exports_external.boolean().optional(),
      on_sale_only: exports_external.boolean().optional(),
      seller_code: exports_external.string().trim().max(40).optional(),
      sort: exports_external.enum(["relevance", "price_asc", "price_desc", "rating", "newest", "popularity", "discount"]).optional().default("relevance"),
      limit: exports_external.number().int().min(1).max(60).optional().default(24),
      offset: exports_external.number().int().min(0).optional().default(0)
    }),
    response: exports_external.object({ products: exports_external.array(productShape), total: exports_external.number() }),
    async handler(ctx, args) {
      const db = fullDb(ctx);
      const actives = await activeStoreIds(ctx);
      let pubs = publicOnly(await productRows(ctx), actives);
      const q = args.query.toLowerCase().trim().replace(/\s+/g, " ");
      if (q) {
        const variantText = new Map;
        if (pubs.length) {
          const vrows = await db.select().from(productVariants).where(and(inArray(productVariants.productId, pubs.map((p) => p.id)), eq(productVariants.isActive, true)));
          for (const v of vrows)
            variantText.set(v.productId, `${variantText.get(v.productId) ?? ""} ${v.label} ${v.sku ?? ""}`);
        }
        const tokens = q.split(" ").filter(Boolean);
        pubs = pubs.filter((p) => {
          const hay = `${p.name} ${p.brand ?? ""} ${p.category} ${p.description}${variantText.get(p.id) ?? ""}`.toLowerCase();
          const words = hay.split(/[\s,.;:!?()\/-]+/);
          return tokens.every((t) => hay.includes(t) || t.length >= 4 && words.some((w) => w.length >= 4 && levenshtein(w, t) <= 2));
        });
        await db.insert(searchEvents).values({ query: q, userId: null, createdAt: new Date });
      }
      if (args.category)
        pubs = pubs.filter((p) => p.category.toLowerCase() === args.category.toLowerCase());
      if (args.brand)
        pubs = pubs.filter((p) => (p.brand ?? "").toLowerCase() === args.brand.toLowerCase());
      if (args.min_price_paisa != null)
        pubs = pubs.filter((p) => p.price_paisa >= args.min_price_paisa);
      if (args.max_price_paisa != null)
        pubs = pubs.filter((p) => p.price_paisa <= args.max_price_paisa);
      if (args.min_rating != null)
        pubs = pubs.filter((p) => (p.rating ?? 0) >= args.min_rating);
      if (args.in_stock_only)
        pubs = pubs.filter((p) => p.stock > 0);
      if (args.on_sale_only)
        pubs = pubs.filter((p) => p.discount_pct > 0);
      if (args.seller_code)
        pubs = pubs.filter((p) => p.seller_code === args.seller_code.toUpperCase());
      const counts = args.sort === "popularity" ? await popularityCounts(ctx) : new Map;
      const relevance = (p) => {
        let score = 0;
        const name2 = p.name.toLowerCase();
        for (const t of q.split(" ").filter(Boolean)) {
          if (name2.startsWith(t))
            score += 4;
          else if (name2.includes(t))
            score += 3;
          else if ((p.brand ?? "").toLowerCase().includes(t) || p.category.toLowerCase().includes(t))
            score += 2;
          else
            score += 1;
        }
        return score;
      };
      const sorted = [...pubs].sort((a, b) => {
        switch (args.sort) {
          case "price_asc":
            return a.price_paisa - b.price_paisa;
          case "price_desc":
            return b.price_paisa - a.price_paisa;
          case "rating":
            return (b.rating ?? -1) - (a.rating ?? -1) || b.review_count - a.review_count;
          case "newest":
            return b.created_at.localeCompare(a.created_at);
          case "popularity":
            return (counts.get(b.id) ?? 0) - (counts.get(a.id) ?? 0);
          case "discount":
            return b.discount_pct - a.discount_pct;
          default:
            return relevance(b) - relevance(a) || (b.rating ?? 0) - (a.rating ?? 0);
        }
      });
      const total = sorted.length;
      return { products: sorted.slice(args.offset, args.offset + args.limit), total };
    }
  }),
  suggestSearch: defineAction({
    request: exports_external.object({ query: exports_external.string().trim().min(1).max(80) }),
    response: exports_external.object({ product_names: exports_external.array(exports_external.string()), categories: exports_external.array(exports_external.string()) }),
    async handler(ctx, args) {
      const pubs = publicOnly(await productRows(ctx), await activeStoreIds(ctx));
      const q = args.query.toLowerCase().trim();
      const names = [...new Set(pubs.map((p) => p.name))];
      const cats = [...new Set(pubs.map((p) => p.category))];
      const rank = (list) => [
        ...list.filter((n) => n.toLowerCase().startsWith(q)),
        ...list.filter((n) => !n.toLowerCase().startsWith(q) && n.toLowerCase().includes(q))
      ];
      return { product_names: rank(names).slice(0, 6), categories: rank(cats).slice(0, 4) };
    }
  }),
